"""The "Generated by GNOST" line added to the Markdown files GNOST writes.

`Footer` builds that line (it can be switched off with `footer = false` in `.gnost.toml`) and
appends it to a document. People who open the file without knowing the tool learn what made it
and how to run it themselves.
"""

from __future__ import annotations

from gnost import __version__

HOME_URL = "https://gnost.readthedocs.io"
TRY_IT = "npx gnost-cli onboard ."


class Footer:
    """One footer line; empty when disabled."""

    def __init__(self, enabled: bool = True, version: str = __version__) -> None:
        self.enabled = enabled
        self.version = version

    def line(self) -> str:
        """The footer as one Markdown line, or an empty string when switched off."""
        if not self.enabled:
            return ""
        return (
            f"<sub>Generated by [GNOST]({HOME_URL}) {self.version}. "
            f"Try it on your own code: `{TRY_IT}`</sub>"
        )

    def append(self, text: str) -> str:
        """The text followed by a rule and the footer; unchanged when disabled."""
        if not self.enabled:
            return text
        return text.rstrip("\n") + f"\n\n---\n\n{self.line()}\n"
